/* v22 masks baked from the 12 supplied poses; smoke and particles are excluded.
   Works on file:// and GitHub Pages: NEVER reads pixels from loaded images.
   The translucent jar uses a baked, slightly inset silhouette and the cat uses approved body silhouettes. */
(() => {
  'use strict';
  const CAT_W = 282, CAT_H = 212, JAR_W = 210, JAR_H = 246;
  const STEP = 3;
  const packed = {"run":[{"bits":"","bounds":[109,68,253,182]},{"bits":"","bounds":[111,72,252,186]},{"bits":"","bounds":[105,61,253,184]},{"bits":"","bounds":[87,57,252,183]},{"bits":"","bounds":[79,47,254,177]},{"bits":"","bounds":[68,50,263,170]},{"bits":"","bounds":[81,49,255,168]},{"bits":"","bounds":[97,51,254,176]},{"bits":"","bounds":[105,53,253,184]},{"bits":"","bounds":[110,58,253,182]},{"bits":"","bounds":[105,62,253,182]},{"bits":"","bounds":[103,66,252,182]}],"jar":{"bits":"","bounds":[7,2,203,244]}};
  const decode = ({bits,bounds},w,h) => {
    const raw = atob(bits);
    const bytes = new Uint8Array(raw.length);
    for(let i=0;i<raw.length;i++) bytes[i]=raw.charCodeAt(i);
    return {bits:bytes,bounds,w,h};
  };
  const ready = {
    run:packed.run.map(d=>decode(d,CAT_W,CAT_H)),
    jar:decode(packed.jar,JAR_W,JAR_H)
  };
  // Gameplay collision stays EXACTLY as in v19: 10 approved silhouettes,
  // independent of the 12 rendered jump poses. Extra drawings never alter difficulty.
  // They all share the same 12 original source frames; no masks need rebaking.
  ready.jump = [0, 2, 3, 4, 5, 6, 7, 8, 9, 11].map(index => ready.run[index]);
  const sample = (m,x,y) => {
    const at=y*m.w+x;
    return (m.bits[at>>3]>>(at&7))&1;
  };
  // Masks were baked at 282 × 212 from the approved character art.
  // Project sampled mask coordinates into the CURRENT draw size; never use the
  // old unscaled bounds or the hitbox will lag behind an enlarged sprite.
  function touching(phase,frame,catX,catY,jar,catDrawW=CAT_W,catDrawH=CAT_H){
    const cat=ready[phase]?.[frame],bottle=ready.jar;
    if(!cat)return false;
    const sx=catDrawW/cat.w,sy=catDrawH/cat.h;
    const cb=cat.bounds,jb=bottle.bounds;
    // Tiny inset avoids collisions from nearly transparent edge pixels.
    const x0=Math.max(catX+cb[0]*sx,jar.x+jb[0]*jar.w/bottle.w);
    const x1=Math.min(catX+cb[2]*sx,jar.x+jb[2]*jar.w/bottle.w);
    const y0=Math.max(catY+cb[1]*sy,jar.y+jb[1]*jar.h/bottle.h);
    const y1=Math.min(catY+cb[3]*sy,jar.y+jb[3]*jar.h/bottle.h);
    if(x1<=x0||y1<=y0)return false;
    let hits=0;
    const startX=Math.ceil(x0/STEP)*STEP;
    const startY=Math.ceil(y0/STEP)*STEP;
    for(let y=startY;y<y1;y+=STEP){
      const cy=Math.floor((y-catY)/sy),jy=Math.floor((y-jar.y)*bottle.h/jar.h);
      if(cy<0||cy>=cat.h||jy<0||jy>=bottle.h)continue;
      for(let x=startX;x<x1;x+=STEP){
        const cx=Math.floor((x-catX)/sx),jx=Math.floor((x-jar.x)*bottle.w/jar.w);
        if(cx<0||cx>=cat.w||jx<0||jx>=bottle.w)continue;
        if(sample(cat,cx,cy)&&sample(bottle,jx,jy)&&++hits>=3)return true;
      }
    }
    return false;
  }
  window.UgolnyCollision = Object.freeze({create: () => Object.freeze({touching})});
})();
